import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        // tails[i]: smallest last letter of a non-decreasing subsequence of length i+1
        char[] tails = new char[s.length()];
        int len = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int lo = 0, hi = len;
            while (lo < hi) { // upper_bound
                int mid = (lo + hi) >>> 1;
                if (tails[mid] <= c) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = c;
            if (lo == len) len++;
        }
        System.out.println(s.length() - len);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	// tails[i]: smallest last letter of a non-decreasing subsequence of length i+1
	tails := []byte{}
	for _, c := range s {
		i := sort.Search(len(tails), func(j int) bool { return tails[j] > c })
		if i == len(tails) {
			tails = append(tails, c)
		} else {
			tails[i] = c
		}
	}
	fmt.Println(len(s) - len(tails))
}
